package org.nonfood.oilplants.web;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.AuditDao;import org.nonfood.oilplants.service.PlantService;import java.io.*;
@WebServlet("/admin/plants/sample/save") public class AdminSampleSaveServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String plant=r.getParameter("plantId");try{WebSupport.requireAdmin(r);long plantId=Long.parseLong(plant),sampleId=Long.parseLong(r.getParameter("sampleId"));new PlantService().updateSample(plantId,sampleId,r.getParameter("sampleLabel"),r.getParameter("oilContent"),r.getParameter("samplePages"),r.getParameter("sampleNote"),r.getParameter("components"),r.getParameter("verificationStatus"),r.getParameter("oilContentStatus"),r.getParameter("componentVerificationStatus"));new AuditDao().log(WebSupport.user(r).getId(),"UPDATE","oil_sample",sampleId,"Plant "+plantId,r.getRemoteAddr());r.getSession().setAttribute("flash","采样记录、含油率及脂肪酸组分核验状态已分别更新。");}catch(Exception e){r.getSession().setAttribute("flash","更新采样记录失败："+e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/plants/form?id="+plant);}}
